import json
from pathlib import Path
p=Path(__file__).parent
q=json.loads((p/'joyteka_quest.json').read_text())
html=r'''<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Дело ML-017 — расследование утечки данных</title>
<style>
:root{color-scheme:dark;--bg:#0a1220;--panel:#121f32;--line:#2b3d55;--text:#eaf0f7;--muted:#adbdcf;--accent:#73d4bc;--amber:#e6bb72}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:16px/1.6 system-ui,Segoe UI,sans-serif}main{max-width:1120px;margin:auto;padding:28px 24px 64px}header{display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);padding-bottom:22px;gap:20px}.brand{font:700 13px/1.5 monospace;letter-spacing:.1em}.brand span{color:var(--accent)}.tag{color:var(--amber);border:1px solid #655433;border-radius:20px;padding:4px 12px;font-size:12px}h1{font-size:clamp(30px,5vw,51px);line-height:1.14;max-width:800px;margin:28px 0 14px;letter-spacing:-.025em}h2{font-size:24px;line-height:1.35}.eyebrow{color:var(--accent);font:12px monospace;letter-spacing:.12em;text-transform:uppercase;margin-top:30px}.intro{color:var(--muted);max-width:900px}.stats{display:flex;gap:20px;flex-wrap:wrap;margin:26px 0 12px;color:var(--muted);font-size:14px}.stats strong{color:var(--text)}progress{display:block;width:100%;height:7px;accent-color:var(--accent);margin-bottom:30px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.card{padding:22px;background:var(--panel);border:1px solid var(--line);text-align:left;border-radius:12px;min-height:190px;cursor:pointer;color:inherit;font:inherit;transition:transform .15s,border-color .15s}.card:hover:not(:disabled){border-color:var(--accent);transform:translateY(-3px)}.card:disabled{opacity:.5;cursor:default}.card.done{border-color:#487e71}.num{display:block;color:var(--accent);font:13px monospace;letter-spacing:.1em}.card strong{display:block;font-size:20px;line-height:1.4;margin:13px 0 10px}.card small{color:var(--muted)}.note{background:#0e1a2c;border:1px solid var(--line);border-radius:12px;padding:22px;color:var(--muted)}a{color:var(--accent)}button{cursor:pointer}button.primary{background:var(--accent);color:#08271e;border:0;border-radius:7px;padding:12px 20px;font:700 15px system-ui}button.secondary{background:transparent;color:var(--text);border:1px solid var(--line);border-radius:7px;padding:11px 17px;font:15px system-ui}button:focus-visible,a:focus-visible,input:focus-visible{outline:3px solid var(--amber);outline-offset:4px}.toolbar{display:flex;gap:12px;flex-wrap:wrap;margin-top:25px}footer{margin-top:32px;border-top:1px solid var(--line);padding-top:18px;font-size:13px;color:var(--muted)}dialog{border:1px solid #46617d;border-radius:14px;background:var(--bg);color:var(--text);padding:0;width:min(920px,95vw);max-height:92vh}dialog::backdrop{background:#000b}.dialog-inner{padding:28px}.dialog-head{display:flex;justify-content:space-between;align-items:flex-start;gap:20px}.close{background:none;color:var(--muted);border:0;font:30px system-ui}.evidence{white-space:pre-wrap;overflow-wrap:anywhere;background:var(--panel);border-left:3px solid var(--accent);padding:22px;border-radius:6px;font:15px/1.8 system-ui;margin:20px 0}label{display:block;margin:16px 0 7px}input{display:block;width:min(100%,400px);background:#15243a;color:var(--text);border:1px solid #48627e;border-radius:6px;padding:12px;font:19px monospace}.message{margin:18px 0;color:var(--amber)}.success{color:var(--accent)}.hidden{display:none!important}#final{padding:30px;border:1px solid var(--accent);border-radius:12px;margin-top:25px}#hint{background:#29271d;color:#f0d3a3;padding:15px;border-radius:8px}.visually-hidden{position:absolute;left:-10000px}@media(max-width:800px){.grid{grid-template-columns:1fr 1fr}}@media(max-width:520px){main{padding:20px 16px}.grid{grid-template-columns:1fr}.card{min-height:155px}.dialog-inner{padding:20px}.stats{gap:10px}.tag{display:none}}
</style>
<main><header><div class="brand">MERIDIAN <span>/ INCIDENT RESPONSE</span></div><span class="tag">Учебный симулятор · 16+</span></header><div class="eyebrow">Материалы расследования / ML-017</div><h1>Расследование<br>утечки данных</h1><p class="intro" id="intro"></p><div class="stats"><span>Доказательства: <strong id="progress">0 / 5</strong></span><span>Время: <strong id="timer">00:00</strong></span><span>Ошибки: <strong id="mistakes">0</strong></span><span>Подсказки: <strong id="hints">0</strong></span></div><progress id="bar" value="0" max="5" aria-label="Прогресс расследования"></progress><section class="grid" id="grid" aria-label="Этапы расследования"></section><section id="final" class="hidden" aria-live="polite"><div class="eyebrow">Расследование завершено</div><h2>Первичный отчёт принят</h2><p id="finaltext"></p><p id="result"></p><button id="report" class="primary">Скачать отчёт о прохождении</button></section><div class="toolbar"><a href="Incident_case_dossier.pdf" target="_blank" rel="noopener">Открыть досье PDF</a><button class="secondary" id="reset">Начать заново</button></div><footer>Пять этапов · 35–45 минут · Все компании, домены и события вымышлены.<br>Решайте по порядку. Ответы вводите цифрами. Результат сохраняется только в этом браузере на этом компьютере.</footer></main>
<dialog id="task"><div class="dialog-inner"><div class="dialog-head"><h2 id="title"></h2><button class="close" id="close" aria-label="Закрыть задание">×</button></div><div class="evidence" id="evidence"></div><form id="answerform"><label for="answer">Ваш ответ</label><input id="answer" name="answer" inputmode="numeric" pattern="[0-9]+" autocomplete="off" required maxlength="12"><div class="toolbar"><button class="primary" type="submit" id="check">Проверить вывод</button><button class="secondary" type="button" id="showhint">Подсказка</button></div></form><p id="message" class="message" role="status"></p><div id="hint" class="hidden"></div><div class="toolbar"><button id="next" class="primary hidden">Продолжить</button></div></div></dialog>
<script id="case-data" type="application/json">__CASE_JSON__</script><script>
'use strict';
const q=JSON.parse(document.getElementById('case-data').textContent),key='meridian-ml017-v1',$=id=>document.getElementById(id);
const fresh=()=>({done:[],mistakes:0,hints:[],start:Date.now(),finish:null});let state=fresh(),current=0;
try{const saved=JSON.parse(localStorage.getItem(key));if(saved&&Array.isArray(saved.done)&&saved.done.every((v,i)=>v===i)&&saved.done.length<=5&&Number.isFinite(saved.start)&&Array.isArray(saved.hints)&&Number.isFinite(saved.mistakes))state=saved}catch(e){}
function save(){try{localStorage.setItem(key,JSON.stringify(state))}catch(e){}}
function elapsed(){return Math.max(0,Math.floor(((state.finish||Date.now())-state.start)/1000))}
function clock(){const s=elapsed();$('timer').textContent=String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0')}
function render(){$('grid').replaceChildren();q.tasks.forEach((task,i)=>{const b=document.createElement('button');b.className='card'+(state.done.includes(i)?' done':'');b.disabled=i>state.done.length;const n=document.createElement('span');n.className='num';n.textContent='ДОКАЗАТЕЛЬСТВО 0'+(i+1);const h=document.createElement('strong');h.textContent=task.title.replace(/^\d+\. /,'');const sub=document.createElement('small');sub.textContent=state.done.includes(i)?'✓ Вывод подтверждён':(b.disabled?'Сначала завершите предыдущий этап':task.object);b.append(n,h,sub);b.onclick=()=>openTask(i);$('grid').append(b)});$('progress').textContent=state.done.length+' / 5';$('bar').value=state.done.length;$('mistakes').textContent=state.mistakes;$('hints').textContent=state.hints.length;$('final').classList.toggle('hidden',state.done.length<5);if(state.done.length===5){$('finaltext').textContent=q.final;$('result').textContent='Проверено 5 из 5 выводов. Ошибок: '+state.mistakes+'. Подсказок: '+state.hints.length+'. Время: '+Math.floor(elapsed()/60)+' мин '+elapsed()%60+' с.'}clock()}
function openTask(i){current=i;const t=q.tasks[i],done=state.done.includes(i);$('title').textContent=t.title;$('evidence').textContent=t.text;$('answer').value='';$('answerform').classList.toggle('hidden',done);$('message').textContent=done?t.feedback:'';$('message').className='message'+(done?' success':'');$('hint').textContent=t.hint;$('hint').classList.toggle('hidden',!state.hints.includes(i));$('next').classList.toggle('hidden',!done);$('task').showModal();if(!done)$('answer').focus()}
$('intro').textContent=q.intro;
$('answerform').onsubmit=e=>{e.preventDefault();if(state.done.includes(current))return;const t=q.tasks[current],answer=$('answer').value.trim();if(answer===t.answer){state.done.push(current);if(state.done.length===5)state.finish=Date.now();save();$('message').textContent='Вывод подтверждён. '+t.feedback;$('message').className='message success';$('answerform').classList.add('hidden');$('next').classList.remove('hidden');render()}else{state.mistakes++;save();$('message').textContent='Вывод не подтверждён. Ещё раз сопоставьте источники и проверьте формат ответа.';$('message').className='message';render()}};
$('showhint').onclick=()=>{if(!state.hints.includes(current)){state.hints.push(current);save();render()}$('hint').classList.remove('hidden')};$('close').onclick=()=>$('task').close();$('next').onclick=()=>{$('task').close();if(state.done.length<5)openTask(state.done.length);else $('final').scrollIntoView({behavior:'smooth'})};$('reset').onclick=()=>{if(confirm('Начать расследование заново? Текущий прогресс будет удалён.')){state=fresh();save();render()}};
$('report').onclick=()=>{const text=q.title+'\nДело ML-017\n\n'+q.final+'\n\n'+$('result').textContent+'\n\nУчебный результат этого браузера. Все данные вымышлены.';const url=URL.createObjectURL(new Blob(['\ufeff'+text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='ML-017_report.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};render();setInterval(clock,1000);
</script></html>'''
# Raw HTML contains JS regex; preserve the backslash and prevent closing the JSON script.
(p/'index.html').write_text(html.replace('__CASE_JSON__',json.dumps(q,ensure_ascii=False).replace('</','<\\/')),encoding='utf-8')
(p/'Start-Quest.cmd').write_bytes(b'@echo off\r\nstart "" "%~dp0index.html"\r\n')
print('built offline quest')
